// 代码静态审查接口
app.post('/api/tech/code-review', (req, res) => {
  const { code } = req.body;
  if (!code) return res.status(400).json({ error: "Missing parameter: code" });

  console.log(`[Tech Expert] Reviewing code quality...`);

  const hasSql = code.toLowerCase().includes("select * from") && !code.toLowerCase().includes("parameterized");
  const hasSecret = code.toLowerCase().includes("api_key") || code.toLowerCase().includes("password");

  const vulnerabilities = [];
  if (hasSql) {
    vulnerabilities.push({
      severity: "high",
      description: "Potential SQL Injection detected. Un-parameterized raw SQL query in use.",
      suggested_fix: "Use parameterized queries or ORM models instead of string concatenation."
    });
  }
  if (hasSecret) {
    vulnerabilities.push({
      severity: "high",
      description: "Hardcoded credential detected. API key or password exposed in raw string.",
      suggested_fix: "Store secrets in environment variables (.env) and load via process.env."
    });
  }

  res.json({
    success: true,
    vulnerabilities,
    dry_violations: code.includes("function") && code.split("function").length > 3
  });
});

// 并发与性能瓶颈诊断接口
app.post('/api/tech/perf-analyze', (req, res) => {
  const { qps, bottleneck } = req.body;
  if (!qps || !bottleneck) {
    return res.status(400).json({ error: "Missing parameters: qps or bottleneck" });
  }

  console.log(`[Tech Expert] Analyzing bottleneck for QPS: ${qps}`);

  res.json({
    success: true,
    recommendation: `根据您的并发目标 ${qps} QPS 以及当前瓶颈 ${bottleneck}，建议采取以下优化方案：\n1. 在数据库前置 Redis 缓存层，采用 Token Bucket 算法进行请求限流削峰。\n2. 对核心表建立符合复合索引优化规则的聚集索引，防止全表扫描。`
  });
});

